const sourceLabel = source => LABEL.source[source]||source||'未确认';
function hasCoordinates(place){return Number.isFinite(place?.lat)&&place.lat>=-90&&place.lat<=90&&Number.isFinite(place?.lng)&&place.lng>=-180&&place.lng<=180;}
function coordinatesFromForm(values){const lat=String(values.lat??'').trim(),lng=String(values.lng??'').trim();if(!lat&&!lng)return {lat:null,lng:null};const latitude=Number(lat),longitude=Number(lng);if(!lat||!lng||!Number.isFinite(latitude)||!Number.isFinite(longitude)||latitude < -90||latitude > 90||longitude < -180||longitude > 180)return null;return {lat:latitude,lng:longitude};}
async function currentCoordinates(){let position;if(isNative())position=await nativePlatform('location');else{if(!navigator.geolocation)throw new Error('浏览器不支持定位，请手动填写 GPS 坐标。');if(!isSecureContext)throw new Error('当前访问方式无法定位；请使用 HTTPS 或在电脑 localhost 体验。');position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{timeout:12000,maximumAge:0})).then(p=>({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}));}if(!position)return null;const {latitude,longitude,accuracy}=position;if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||latitude < -90||latitude > 90||longitude < -180||longitude > 180)throw new Error('定位结果无效');const accuracyText=Number.isFinite(accuracy)?`\n定位精度约 ${Math.round(accuracy)} 米。`:'';return confirm(`当前位置（GPS/WGS84）：${latitude.toFixed(5)}, ${longitude.toFixed(5)}${accuracyText}\n确认使用这个位置吗？`)?{lat:latitude,lng:longitude}:null;}
async function navigateTo(place){if(!hasCoordinates(place))return;if(isNative()){await systemOperation(()=>nativePlatform('amapNavigate',{latitude:place.lat,longitude:place.lng,name:place.name}));return;}const query=new URLSearchParams({sourceApplication:'KF-Note',lat:String(place.lat),lon:String(place.lng),dev:'1',style:'2',poiname:place.name||'房源'});location.href=`androidamap://navi?${query}`;}
function backupDue(){if(!data.houses.length)return false;const last=Date.parse(data.settings.lastBackupAt||'')||0;const dates=data.houses.flatMap(h=>[h.updatedAt,...h.visits.map(v=>v.updatedAt)]).concat(data.photos.map(p=>p.createdAt));return Date.now()-last>30*86400000&&dates.some(value=>Date.parse(value)>last);}

function toast(message,error=false){clearTimeout(toastTimer);toastEl.textContent=message;toastEl.className='toast'+(error?' error':'');toastEl.hidden=false;toastTimer=setTimeout(()=>toastEl.hidden=true,error?6000:3500);}
function savedStatus(){const el=app.querySelector('#save-state');if(el)el.innerHTML=`<span class="save-dot"></span>${saveError?'保存失败':pending?'保存中…':'已保存到本机'}${saveError?'<button class="btn ghost small" data-action="retry-save">重试</button>':''}`;el?.classList.toggle('error',!!saveError);}
function commit(operation){pending++;saveError=null;savedStatus();const task=saveTask.catch(()=>{}).then(operation);saveTask=task;task.then(()=>{pending--;savedStatus();},error=>{pending--;saveError=error;savedStatus();toast(error.message||'保存失败，请重试',true);});return task;}
function persist(){const snapshot=structuredClone(data);return commit(()=>saveState(snapshot));}
async function flush(){try{await saveTask;}catch{throw new Error('当前内容尚未保存成功，请先重试保存。');}}
async function go(page){await flush();view.page=page;render();window.scrollTo({top:0,behavior:'instant'});}
async function chooseMode(mode){await flush();data.settings.mode=mode;view.filter='all';await persist();await go('list');}
async function openHouse(id,tab='diary'){await flush();view.houseId=id;view.tab=tab;view.visitId=latestVisit(house())?.id||null;view.section='whole';await go('detail');}
function attrs(scope,id,field){return `data-scope="${scope}" data-id="${escape(id||'')}" data-field="${field}"`;}
function input(label,scope,id,field,value,type='text',extra=''){return `<label>${label}<input ${attrs(scope,id,field)} type="${type}" value="${escape(value)}" ${extra}></label>`;}
function area(label,scope,id,field,value,placeholder=''){return `<label>${label}<textarea ${attrs(scope,id,field)} placeholder="${placeholder}">${escape(value)}</textarea></label>`;}
function select(label,scope,id,field,value,options,extra=''){const opts={...options};if(value!=null&&!Object.hasOwn(opts,value))opts[value]=value;return `<label>${label}<select ${attrs(scope,id,field)} ${extra}>${Object.entries(opts).map(([key,text])=>`<option value="${escape(key)}" ${key===String(value)?'selected':''}>${escape(text)}</option>`).join('')}</select></label>`;}
function checkbox(label,scope,id,field,checked){return `<label class="check-label"><input type="checkbox" ${attrs(scope,id,field)} ${checked?'checked':''}>${label}</label>`;}
function pageHeading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted subline">${description}</p></div>${action}</div>`;}
function summary(h){const cost=monthlyReference(h);return `${cost.unknown?'已知部分 ':''}¥${money(cost.known)}/月${cost.unknown?' + '+cost.unknown+' 项未确认':''}`;}
function costPanel(h){const cost=monthlyReference(h);return `<div class="cost-summary"><div class="muted">${h.mode==='rent'?'固定月支出参考':'持有期固定月支出参考'}</div><div class="cost-amount" id="monthly-reference">${summary(h)}</div><p class="muted">${h.mode==='buy'?'不含房价、贷款、交易税费':'不含押金、一次性费用'}，水电燃气按用量另计。</p><div class="cost-parts" id="monthly-parts">${cost.items.map(x=>`${escape(x.name)}：${x.monthly===null?escape(x.reason):'¥'+money(x.monthly)+'/月'}`).join(' · ')}${cost.hasAmortized?'<br>年费 / 采暖季为全年摊销参考，非实际月账单。':''}</div></div>`;}
function render(){
  const active=view.page==='detail'||view.page==='new'?'list':view.page;
  const navItem=(page,name,ico)=>`<button data-page="${page}" class="${active===page?'active':''}" ${active===page?'aria-current="page"':''}>${icon(ico)}${name}</button>`;
  app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-symbol">${icon('house')}</span>看房日记</div><nav class="side-nav" aria-label="主导航">${navItem('list','看过的房子','house')}${navItem('compare','房源对比','compare')}${navItem('settings',backupDue()?'设置与备份 · 待备份':'设置与备份','settings')}</nav><div class="side-foot">把现场的感受留下来。<br>个人记录 · 离线优先<br><span>${isNative()?'安卓离线版':'手机网页交互原型'}</span></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand"><span class="brand-symbol">${icon('house')}</span>看房日记</div><div class="save-state" id="save-state" role="status"></div><div class="mode-toggle" aria-label="买房或租房"><button data-mode="buy" class="${data.settings.mode==='buy'?'active':''}">买房</button><button data-mode="rent" class="${data.settings.mode==='rent'?'active':''}">租房</button></div></header><main class="content" id="main"></main></div>${view.page!=='entry'?`<nav class="mobile-nav" aria-label="手机导航">${navItem('list','房源','house')}${navItem('compare','对比','compare')}${navItem('settings',backupDue()?'设置 · 待备份':'设置','settings')}</nav>`:''}</div>`;
  const main=app.querySelector('#main');
  if(view.page==='entry')main.innerHTML=entryPage();
  if(view.page==='list')main.innerHTML=listPage();
  if(view.page==='new')main.innerHTML=newPage();
  if(view.page==='detail')main.innerHTML=detailPage();
  if(view.page==='compare')main.innerHTML=comparePage();
  if(view.page==='settings')main.innerHTML=settingsPage();
  savedStatus();hydratePhotos().catch(report);
}
function entryPage(){return `<section class="hero"><div class="eyebrow">A PLACE TO CALL HOME</div><h1>下一站，<br>是怎样的家？</h1><p class="hero-sentence">记下每一次心动，也留下那些犹豫。<br>把看过的房子放在一起，慢慢做决定。</p><div class="hero-choices"><button class="hero-choice" data-mode="buy"><span class="choice-icon warm">${icon('key')}</span><h2>我要买房</h2><p class="muted">记录户型、产权与长期居住体验 →</p></button><button class="hero-choice" data-mode="rent"><span class="choice-icon">${icon('house')}</span><h2>我要租房</h2><p class="muted">记录月租、费用与居住约定 →</p></button></div><div class="hero-foot"><span>${icon('shield')}无需注册</span><span>${icon('image')}图文分区记录</span><span>${icon('compare')}同维度对比</span></div><button class="btn ghost" data-action="demo" style="margin-top:24px">载入虚构示例，先体验一下 →</button></section>`;}
function card(h){const last=latestVisit(h);const selected=data.compare[h.mode].includes(h.id);return `<article class="house-card" data-open-house="${h.id}"><div class="cover ${h.mode}">${h.coverId?`<img data-photo="${h.coverId}" alt="${escape(h.name)}的封面">`:icon('house')}<button class="cover-conclusion ${h.conclusion}" data-house-status="${h.id}" aria-label="修改房源状态：${LABEL.conclusion[h.conclusion]}">${LABEL.conclusion[h.conclusion]} ▾</button>${!h.coverId?'<span class="cover-note">添加第一张照片，留住现场印象</span>':''}</div><div class="house-body"><button class="house-title" data-open-house="${h.id}">${escape(h.name)}</button><p class="muted">${escape(channelLabel(h))} · ${escape(h.address||'地址待补充')}</p><div class="house-price">${h.price===null?'价格待补充':money(h.price)}<span>${h.price!==null?(h.mode==='buy'?'万元':'元 / 月'):''}</span></div><p class="muted">${h.area!==null?money(h.area)+' ㎡':'面积待补充'} · ${escape(h.layout||'户型待补充')}</p><p class="house-observation">${escape(last?.impression||'还没有整体印象，去记下第一眼的感受。')}</p><div class="row"><span class="tag">宠物：${LABEL.pets[h.terms.pets]||'未确认'}</span><span class="tag ${monthlyReference(h).unknown?'warm':''}">费用 ${monthlyReference(h).unknown} 项未确认</span></div><div class="house-footer"><span class="muted">${h.visits.length} 次看房 · ${date(last?.at)}</span><label class="check-label"><input type="checkbox" data-compare="${h.id}" ${selected?'checked':''}>对比</label></div></div></article>`;}
function listPage(){const houses=group().sort((a,b)=>Date.parse(latestVisit(b)?.at||b.createdAt)-Date.parse(latestVisit(a)?.at||a.createdAt));const filtered=houses.filter(h=>view.filter==='all'||h.conclusion===view.filter);const current=filtered.filter(h=>h.conclusion!=='excluded'),excluded=filtered.filter(h=>h.conclusion==='excluded');return pageHeading(`${modeLabel()} · PERSONAL JOURNAL`,'看过的家',`${houses.length} 套记录 · ${houses.filter(h=>h.conclusion==='favorite').length} 套心仪`, `<button class="btn primary" data-page="new">${icon('plus')}新建房子</button>`)+`<div class="filters">${Object.entries({all:'全部',...LABEL.conclusion}).map(([key,label])=>`<button class="chip ${view.filter===key?'active':''}" data-filter="${key}">${label}</button>`).join('')}</div>${!houses.length?`<div class="empty">${icon('house')}<h2>从第一套房子开始</h2><p class="muted">只填一个名字，就可以边看边记录。</p><div class="row"><button class="btn primary" data-page="new">记录第一套房子</button><button class="btn" data-action="demo">体验虚构示例</button></div></div>`:`<div class="house-grid">${current.map(card).join('')}</div>${excluded.length?`<details class="excluded-list" ${view.filter==='excluded'?'open':''}><summary>已排除 · ${excluded.length} 套，记录仍保留</summary><div class="house-grid">${excluded.map(card).join('')}</div></details>`:''}${!filtered.length?'<div class="empty"><p class="muted">这个分类暂时没有房源。</p></div>':''}`}`;}
function newPage(){return `<button class="btn ghost" data-page="list">${icon('arrow')}返回房源</button>${pageHeading(modeLabel(),'记录一套新房子','先填名字，其他信息可以现场慢慢补。')}<form id="new-house" class="panel"><div class="fields"><label class="full">房源名称 *<input name="name" required placeholder="例如：春和里 3 栋 502" maxlength="100"></label><label>${data.settings.mode==='buy'?'总价（万元）':'月租（元/月）'}<input name="price" type="number" min="0" step="any" placeholder="选填"></label><label>面积（㎡）<input name="area" type="number" min="0.01" step="any" placeholder="选填"></label><label>面积口径<select name="areaBasis">${Object.entries(LABEL.areaBasis).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label>户型<input name="layout" placeholder="例如：2室1厅1卫"></label><label class="full">小区 / 地址<input name="address" placeholder="可手写地址，不需要定位权限"></label><label>纬度（GPS/WGS84，选填）<input name="lat" type="number" min="-90" max="90" step="any" placeholder="-90 至 90"></label><label>经度（GPS/WGS84，选填）<input name="lng" type="number" min="-180" max="180" step="any" placeholder="-180 至 180"></label><div class="full"><button class="btn" type="button" data-action="location">${icon('pin')}使用当前位置</button><p class="field-hint">坐标为 GPS/WGS84；手填时请勿使用高德地图坐标。只有确认创建后才保存。</p></div><input type="hidden" name="locationConfirmed" value="false"><label>房源渠道<select name="channel">${Object.entries(LABEL.channel).map(([key,label])=>`<option value="${key}">${key==='owner'&&data.settings.mode==='buy'?'业主直售':label}</option>`).join('')}</select></label><label>联系人称呼<input name="contactName" placeholder="选填"></label><label class="full">联系电话<input name="phone" type="tel" placeholder="选填"></label></div><div class="row spread" style="margin-top:24px"><span class="muted">创建后直接开始第一篇日记</span><button class="btn primary">创建并开始记录 →</button></div></form>`;}
function visitOptions(h){return [...h.visits].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).map(v=>`<option value="${v.id}" ${view.visitId===v.id?'selected':''}>${date(v.at)} · ${localDateTime(v.at).slice(11)} 看房</option>`).join('');}
function journalSection(h,v,section){const text=v.notes[section]?.text||'';const photos=data.photos.filter(p=>p.houseId===h.id&&p.visitId===v.id&&p.sectionKey===section);const prompts={environment:'小区内部绿化、安保、物业、停车和公共空间是否满意？',traffic:'地铁 / 公交、步行体验，以及到公司的通勤。',amenities:'周边买菜、就医、休闲和日常办事是否方便？',layout:'实际布局、动线，和户型图是否一致？',whole:'整体装修、采光、通风、噪音、异味、家具与取暖。'};return `<h3>${escape(sectionName(h,section))}</h3><p class="muted subline">${prompts[section]||'大小、采光、通风、布局，记下观察，也可以先拍照。'}</p><div class="photo-grid">${photos.map(p=>`<button class="photo-tile" data-open-photo="${p.id}" aria-label="查看 ${escape(p.caption||p.filename)}">${isVideo(p)?'<span class="video-tile"><span>▶</span><small>视频</small></span>':`<img data-photo="${p.id}" alt="${escape(p.caption||sectionName(h,section)+'照片')}">`}${p.caption?`<span class="photo-caption">${escape(p.caption)}</span>`:''}</button>`).join('')}<button class="photo-tile photo-add" data-action="choose-photo">${icon('image')}照片／视频</button><button class="photo-tile photo-add" data-action="take-photo">${icon('camera')}现场拍照</button><button class="photo-tile photo-add" data-action="take-video">${icon('camera')}现场拍视频</button></div>${area('本次文字记录','note',section,'text',text,'可以先拍照或添加视频，回家再补充文字。')}<p class="field-hint">自动保存 · 不同看房时间的记录分别保留</p>${section==='traffic'?commutePage(v):''}${section==='layout'||section==='whole'?'<button class="btn ghost small" data-action="sync-facts">更新本次核实的房源事实 →</button>':''}`;}
function photoInputs(){return `<input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif,video/mp4,video/webm,video/3gpp" multiple hidden><input id="camera-input" type="file" accept="image/*" capture="environment" hidden><input id="video-camera-input" type="file" accept="video/*" capture="environment" hidden>`;}
function basicPage(h){const v=visit();const basics=[['environment','小区配套'],['traffic','交通'],['amenities','生活配套']];if(!basics.some(([key])=>key===view.section))view.section='environment';return `<div class="detail-layout two-column"><div class="stack"><section class="panel"><div class="panel-heading"><h2>房子的基本信息</h2><span class="tag">事实信息</span></div><div class="fields">${input('房源名称','house',h.id,'name',h.name)}${input(h.mode==='buy'?'总价（万元）':'月租（元/月）','house',h.id,'price',h.price,'number','min="0" step="any"')}${input('面积（㎡）','house',h.id,'area',h.area,'number','min="0.01" step="any"')}${select('面积口径','house',h.id,'areaBasis',h.areaBasis,LABEL.areaBasis)}${input('户型','house',h.id,'layout',h.layout)}${select('朝向','house',h.id,'direction',h.direction,LABEL.direction)}${input('楼层','house',h.id,'floor',h.floor)}${input('总楼层','house',h.id,'totalFloors',h.totalFloors)}${select('电梯','house',h.id,'elevator',h.elevator,LABEL.elevator)}${select('个人结论','house',h.id,'conclusion',h.conclusion,LABEL.conclusion)}<div class="full">${input('小区 / 地址','house',h.id,'address',h.address)}</div><div class="full">${area('房源链接／分享口令','house',h.id,'sourceLink',h.sourceLink||'','粘贴网址、分享口令或完整分享文本')}</div><div class="full">${input('排除原因（选填）','house',h.id,'rejectionReason',h.rejectionReason)}</div>${input('纬度（GPS/WGS84，选填）','house',h.id,'lat',h.lat,'number','min="-90" max="90" step="any"')}${input('经度（GPS/WGS84，选填）','house',h.id,'lng',h.lng,'number','min="-180" max="180" step="any"')}</div><button class="btn wide" style="margin-top:17px" data-action="location">${icon('pin')}获取当前位置并确认</button><p class="field-hint">坐标为 GPS/WGS84；手填时请勿使用高德地图坐标。记录定位不等于确认房源位置。</p>${hasCoordinates(h)?`<button class="btn wide" style="margin-top:10px" data-navigate-house="${h.id}">高德地图导航</button>`:''}${h.planId?`<button class="photo-tile" data-open-photo="${h.planId}" style="width:100%;max-height:220px;margin-top:16px"><img data-photo="${h.planId}" alt="户型图"></button>`:''}</section>${v?`<section class="panel"><div class="visit-toolbar"><label>选择看房记录<select id="basic-visit-picker" aria-label="基本信息页选择看房记录">${visitOptions(h)}</select></label></div><div class="note-tabs">${basics.map(([key,name])=>`<button class="${view.section===key?'active':''}" data-section="${key}">${name}</button>`).join('')}</div>${journalSection(h,v,view.section)}</section>`:`<section class="panel"><h2>生活记录</h2><p class="muted">还没有看房记录。</p><button class="btn" data-action="new-visit">新增看房记录</button></section>`}</div><div class="stack"><section class="panel"><div class="panel-heading"><h2>渠道与联系人</h2><button class="btn ghost small" data-action="add-contact">＋ 添加</button></div>${select('房源渠道','house',h.id,'channel',h.channel,{...LABEL.channel,owner:h.mode==='buy'?'业主直售':'房东直租'})}${h.contacts.map(c=>`<div class="contact-row"><div><div class="contact-name">${escape(c.name)} <span class="tag">${escape({agent:'中介',owner:h.mode==='buy'?'业主':'房东',other:'其他'}[c.role]||'其他')}</span></div><p class="contact-phone">${escape(c.phone||'电话未填写')}</p><p class="muted">${escape(c.company||c.remark||'')}</p></div><div class="contact-actions">${c.phone?`<a class="btn small" href="tel:${escape(c.phone.replace(/[^+\d]/g,''))}" aria-label="拨号 ${escape(c.name)}">${icon('phone')}</a>`:''}<button class="btn ghost small" data-edit-contact="${c.id}">编辑</button></div></div>`).join('')||'<p class="muted subline">还没有联系人，可记录中介或房东电话。</p>'}</section><section class="panel"><div class="panel-heading"><h2>空间列表</h2><button class="btn ghost small" data-action="add-space">＋ 添加空间</button></div>${h.spaces.map(s=>`<div class="space-row"><span>${escape(s.name)} <span class="muted">${LABEL.space[s.type]}</span></span><button class="btn ghost small" data-rename-space="${s.id}">重命名</button></div>`).join('')}<p class="field-hint">复看沿用这些空间，重命名不会丢失历史记录。</p></section>${h.mode==='buy'?ownershipPage(h):''}<button class="btn danger wide" data-action="delete-house">${icon('trash')}删除这套房源和关联记录</button></div></div>${photoInputs()}`;}function detailPage(){const h=house();if(!h)return '<p>房源不存在。</p>';if(!visit()&&h.visits.length)view.visitId=latestVisit(h).id;const single=unitPrice(h);return `<button class="btn ghost" data-page="list">${icon('arrow')}全部房源</button><header class="detail-header"><div class="row spread"><h1>${escape(h.name)}</h1><label class="check-label"><input type="checkbox" data-compare="${h.id}" ${data.compare[h.mode].includes(h.id)?'checked':''}>加入对比</label></div><p class="muted">${escape(channelLabel(h))} · ${escape(h.address||'地址待补充')}</p><div class="detail-summary"><span class="house-price">${escape(priceText(h))}</span><span class="muted">${h.area===null?'面积待补充':money(h.area)+' ㎡ · '+escape(LABEL.areaBasis[h.areaBasis]||h.areaBasis)} · ${escape(h.layout||'户型待补充')}</span></div>${single!==null?`<p class="muted">单价 ¥${money(single)}/㎡ · ${escape(h.areaBasis)}</p>`:''}</header><div class="row" style="margin-bottom:16px"><button class="btn" data-action="generate-introduction">生成房源介绍</button></div><div class="tabs" aria-label="房源详情">${[['basic','基本信息'],['diary','看房日记'],['fees','费用与约定']].map(([key,name])=>`<button class="${view.tab===key?'active':''}" data-tab="${key}">${name}</button>`).join('')}</div>${view.tab==='basic'?basicPage(h):view.tab==='fees'?feesPage(h):diaryPage(h)}`;}
function ownershipPage(h){const o=h.ownership;const year=new Date().getFullYear();return `<section class="panel"><div class="panel-heading"><h2>产权信息</h2><span class="tag warm">仅记录，不算税</span></div><div class="fields">${input('建成年份','ownership',h.id,'builtYear',o.builtYear,'number','min="1800" max="2200" step="1"')}${select('产权性质','ownership',h.id,'nature',o.nature,LABEL.nature)}${input('产权年限（年）','ownership',h.id,'years',o.years,'number','min="1" max="1000" step="1"')}${input('产权起始年份','ownership',h.id,'startYear',o.startYear,'number','min="1800" max="2200" step="1"')}${select('卖方持有年限','ownership',h.id,'held',o.held,LABEL.held)}${select('卖方家庭唯一住房','ownership',h.id,'sole',o.sole,LABEL.sole)}<div class="full">${select('确认来源','ownership',h.id,'source',o.source,LABEL.source)}</div></div><p class="field-hint">${o.builtYear!==null?'房龄约 '+Math.max(0,year-o.builtYear)+' 年':'房龄未确认'} · ${o.years!==null&&o.startYear!==null?'剩余约 '+Math.max(0,o.startYear+o.years-year)+' 年（按年份估算）':'剩余年限未确认'}</p>${o.nature==='commercial'?'<p class="field-hint warn">建议核对水电燃气是否为商用计价。</p>':''}</section>`;}
function diaryPage(h){const v=visit();if(!v)return `<div class="empty"><h2>开始一篇看房日记</h2><button class="btn primary" data-action="new-visit" style="margin-top:20px">新增看房日记</button></div>`;const diaryKeys=['layout','whole',...h.spaces.map(s=>'space:'+s.id)];if(!diaryKeys.includes(view.section))view.section='whole';return `<div class="visit-toolbar"><select id="visit-picker" aria-label="选择看房日记">${visitOptions(h)}</select><div class="row"><button class="btn" data-action="new-visit">${icon('plus')}复看记录</button><button class="btn ghost small danger" data-action="delete-visit">删除本次</button></div></div><div class="detail-layout"><section class="panel"><div class="panel-heading"><h2>这一次的整体感受</h2><span class="tag">只记录本次</span></div><div class="fields"><div class="full">${input('看房时间','visit',v.id,'at',localDateTime(v.at),'datetime-local')}</div><div class="full">${area('总体印象','visit',v.id,'impression',v.impression,'第一眼是什么感觉？')}</div>${area('喜欢的地方','visit',v.id,'pros',v.pros,'记下优点')}${area('顾虑 / 待确认','visit',v.id,'cons',v.cons,'复看时重点检查')}</div></section><section class="panel"><div class="panel-heading"><h2>按区域留住细节</h2><button class="btn ghost small" data-action="add-space">＋ 空间</button></div><div class="note-tabs">${[['layout','户型'],['whole','整屋情况'],...h.spaces.map(s=>['space:'+s.id,s.name])].map(([key,name])=>`<button class="${view.section===key?'active':''}" data-section="${key}">${escape(name)}</button>`).join('')}</div>${journalSection(h,v,view.section)}</section></div>${photoInputs()}`;}function commutePage(v){return `<hr class="field-divider"><div class="panel-heading"><h3>到同一目的地的通勤</h3><button class="btn ghost small" data-action="add-commute">＋ 添加</button></div>${v.commutes.map((c,i)=>`<div class="fields" style="margin:16px 0"><div class="full"><span class="tag">${escape(data.settings.targets.find(t=>t.id===c.targetId)?.name||'目的地')}</span><button class="btn ghost small danger" data-delete-commute="${i}">移除</button></div>${select('交通方式','commute',String(i),'method',c.method,LABEL.method)}${input('耗时（分钟）','commute',String(i),'minutes',c.minutes,'number','min="0" step="any"')}<div class="full">${input('记录来源','commute',String(i),'source',c.source)}</div></div>`).join('')||'<p class="muted">还没有记录。先在设置添加公司、学校等目的地。</p>'}`;}
function fixedSelected(e){if(e.status==='free'||e.status==='included'||e.payer==='other')return 'free';if(e.status==='known'&&e.payer==='self')return 'known';return '';}
function fixedStatusField(e){const value=fixedSelected(e);return `<label>费用状态<select ${attrs('expense',e.id,'status')}><option value="" disabled ${value===''?'selected':''}>请选择</option><option value="free" ${value==='free'?'selected':''}>免费</option><option value="known" ${value==='known'?'selected':''}>自费</option></select></label>`;}
function expenseText(e,fixed=false){if(fixed&&fixedSelected(e)==='free')return '免费';if(e.status!=='known')return LABEL.status[e.status]||'未确认';return e.amount===null?'金额待补充':`¥${money(e.amount)}${e.unit==='sqm'?'/㎡':''}${e.period==='once'?'（一次性）':'/'+LABEL.period[e.period]}`;}
function expenseEditor(e,fixed=false){const status=fixed?fixedStatusField(e):select('费用状态','expense',e.id,'status',e.status,LABEL.status);const fixedValue=fixedSelected(e);const fixedPayer=fixed?(fixedValue==='free'?'other':fixedValue==='known'?'self':'unknown'):e.payer;const payer=fixed?select('承担方','expense',e.id,'payer',fixedPayer,LABEL.payer,'disabled'):select('承担方','expense',e.id,'payer',e.payer,LABEL.payer);const showAmount=e.status==='known'&&(!fixed||fixedValue==='known'||fixedValue==='');return `<details class="fee-card" data-expense="${e.id}" ${view.openExpenses.has(e.id)?'open':''}><summary><span class="fee-name">${escape(e.name)}</span><span class="fee-value">${expenseText(e,fixed)}</span></summary><div class="fields">${status}${payer}${showAmount?`${input('金额（元）','expense',e.id,'amount',e.amount,'number',`min="0" step="any" ${fixed?'required':''}`)}${select('收费周期','expense',e.id,'period',e.period,LABEL.period)}${select('计费单位','expense',e.id,'unit',e.unit,LABEL.unit)}${e.unit==='sqm'?input('实际计费面积（㎡）','expense',e.id,'billingArea',e.billingArea,'number','min="0.01" step="any"'):'<p class="field-hint">按套金额，不乘房源面积。</p>'}${e.period==='season'?`<div class="full">${checkbox('已确认每年收取一个采暖季费用','expense',e.id,'seasonAnnual',e.seasonAnnual)}<p class="field-hint">未确认频率时不做月费换算。</p></div>`:''}`:''}${fixed&&e.status==='known'&&fixedValue===''?'<p class="field-hint full">原金额保留，请选择费用状态确认承担方式。</p>':''}<div class="full">${select('确认来源','expense',e.id,'source',e.source,LABEL.source)}</div><div class="full">${input('备注','expense',e.id,'remark',e.remark)}</div></div></details>`;}function agencyAmount(period,expense){return input(period==='once'?'一次性中介费（元）':'每月服务费（元）','agency',period,'amount',expense?.amount??null,'number','min="0" step="any"');}
function feesPage(h){const t=h.terms;const once=onceReference(h);const agencies=h.expenses.filter(e=>e.category==='agency');const agencyOnce=agencies.find(e=>e.period==='once');const agencyMonth=agencies.find(e=>e.period==='month');const extraAgency=agencies.filter(e=>e!==agencyOnce&&e!==agencyMonth);const otherOnce=h.expenses.filter(e=>e.period==='once'&&e.category!=='agency');return costPanel(h)+`<div class="detail-layout two-column"><div class="stack"><section class="panel"><div class="panel-heading"><h2>固定费用</h2><button class="btn ghost small" data-action="add-expense">＋ 费用</button></div>${h.expenses.filter(e=>e.period!=='once'&&e.category!=='agency').map(e=>expenseEditor(e,true)).join('')}<p class="field-hint">未知不当作免费。按平方米计费须另外确认计费面积。</p></section><section class="panel"><div class="panel-heading"><h2>中介费</h2></div><div class="fields">${agencyAmount('once',agencyOnce)}${agencyAmount('month',agencyMonth)}</div><p class="muted" id="once-reference">所有一次性费用：已知自己承担 ¥${money(once.known)} · ${once.unknown} 项未确认</p>${extraAgency.map(e=>expenseEditor(e)).join('')}<p class="field-hint">一次性费用不计入月费；每月服务费计入固定月支出。</p></section>${h.mode==='buy'||otherOnce.length?`<section class="panel"><div class="panel-heading"><h2>${h.mode==='buy'?'交易税费':'其他一次性费用'}</h2><span class="tag warm">不计入月费</span></div>${otherOnce.map(e=>expenseEditor(e)).join('')}<p class="field-hint">税费只记录报价和来源，不自动计算。</p></section>`:''}<section class="panel"><div class="panel-heading"><h2>水电燃气</h2><span class="tag">按用量另计</span></div>${h.utilities.map(u=>`<div class="utility-block"><h3>${LABEL.utility[u.type]} ${u.pricing==='commercial'?'<span class="tag warm">商用</span>':''}</h3><div class="fields">${select('计价类型','utility',u.type,'pricing',u.pricing,LABEL.pricing)}${input('单价（'+({water:'元/吨',electricity:'元/度',gas:'元/立方米'}[u.type])+')','utility',u.type,'rate',u.rate,'number','min="0" step="any"')}${select('缴费方式','utility',u.type,'payment',u.payment,LABEL.payment)}${select('确认来源','utility',u.type,'source',u.source,LABEL.source)}</div></div>`).join('')}</section></div><div class="stack"><section class="panel"><div class="panel-heading"><h2>整屋与居住约定</h2><span class="tag">房源事实</span></div><div class="fields">${select('取暖方式','terms',h.id,'heating',t.heating,LABEL.heating)}${select('取暖信息来源','terms',h.id,'heatingSource',t.heatingSource||t.source,LABEL.source)}${select('家具家电情况','terms',h.id,'furnitureStatus',t.furnitureStatus,LABEL.furnitureStatus)}${select('家具信息来源','terms',h.id,'furnitureSource',t.furnitureSource||t.source,LABEL.source)}<div class="full"><label>已配备家具家电</label><div class="check-grid">${[...new Set([...furnitureOptions,...t.furniture])].map(item=>`<label><input type="checkbox" data-furniture="${escape(item)}" ${t.furniture.includes(item)?'checked':''}>${escape(item)}</label>`).join('')}</div><button class="btn ghost small" data-action="custom-furniture">＋ 其他家具 / 家电</button></div>${select('是否允许养宠物','terms',h.id,'pets',t.pets,LABEL.pets)}${select('宠物约定来源','terms',h.id,'petsSource',t.petsSource||t.source,LABEL.source)}<div class="full">${area('宠物条件','terms',h.id,'petConditions',t.petConditions,'例如：只允许猫；需确认额外押金。')}</div><div class="full">${area('家具家电状况备注','terms',h.id,'furnitureNotes',t.furnitureNotes||'','例如：冰箱正常，沙发有破损。')}</div></div><p class="field-hint">现场的装修、采光、异味等观察放在每次看房日记里。</p></section>${h.mode==='rent'?`<section class="panel"><div class="panel-heading"><h2>租房条款</h2></div><div class="fields">${input('押金','terms',h.id,'deposit',t.deposit,'number','min="0" step="any"')}${select('押金单位','terms',h.id,'depositUnit',t.depositUnit,{amount:'元',months:'个月租金'})}<div class="full">${input('付款方式','terms',h.id,'payment',t.payment,'text','placeholder="例如：押一付三"')}</div><div class="full">${input('租期','terms',h.id,'lease',t.lease,'text','placeholder="例如：一年，可续租"')}</div><div class="full">${select('租房条款来源','terms',h.id,'rentSource',t.rentSource||t.source,LABEL.source)}</div></div><p class="field-hint">押金不计入固定月支出。</p></section>`:''}<section class="notice">${icon('shield')}<span>口头报价与约定保留来源，未确认的事项留待复看或核对材料。</span></section></div></div>`;}function observedCell(h,key){const result=latestNote(h,key,data.photos);if(!result)return '<span class="muted">待补充</span>';const relevant=data.photos.filter(p=>p.houseId===h.id&&p.visitId===result.visit.id&&p.sectionKey===key);const photo=relevant.find(p=>!isVideo(p))||relevant[0];return `<button class="cell-open" data-observation-house="${h.id}" data-observation-visit="${result.visit.id}" data-observation-key="${key}">${escape(result.note.text)||(isVideo(photo)?'视频记录':'照片记录')}${photo?(isVideo(photo)?'<span class="tag">▶ 视频记录</span>':`<img class="cell-photo" data-photo="${photo.id}" alt="${escape(sectionName(h,key))}">`):''}<span class="cell-date">看房：${date(result.visit.at)} →</span></button>`;}
function commuteCell(h){const candidates=[...h.visits].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));return data.settings.targets.map(target=>{const records=new Map();for(const v of candidates)for(const c of v.commutes.filter(c=>c.targetId===target.id))if(!records.has(c.method))records.set(c.method,{v,c});return `<div>${escape(target.name)}：${records.size?[...records.values()].map(({v,c})=>`${escape(LABEL.method[c.method]||c.method)} ${c.minutes===null?'未确认':money(c.minutes)+'分钟'}<span class="cell-date">${date(v.at)} · ${escape(c.source||'来源未确认')}</span>`).join(''):'未记录'}</div>`;}).join('')||'尚未设置目的地';}
function comparePage(){const all=group();const picked=data.compare[data.settings.mode].map(id=>all.find(h=>h.id===id)).filter(Boolean);const rows=[['价格',h=>escape(priceText(h))],['面积 / 户型',h=>`${h.area===null?'未确认':money(h.area)+'㎡'} · ${escape(LABEL.areaBasis[h.areaBasis]||h.areaBasis)}<br>${escape(h.layout||'待补充')}`],['渠道',h=>escape(channelLabel(h))],['个人结论',h=>LABEL.conclusion[h.conclusion]],['月支出参考',h=>escape(summary(h))],['通勤',commuteCell],['小区配套',h=>observedCell(h,'environment')],['生活配套',h=>observedCell(h,'amenities')],['户型观察',h=>observedCell(h,'layout')],['整屋观察',h=>observedCell(h,'whole')],['取暖方式',h=>(LABEL.heating[h.terms.heating]||'未确认')+`<span class="cell-date">${escape(sourceLabel(h.terms.heatingSource||h.terms.source))}</span>`],...['property','heating','network'].map(category=>[{'property':'物业费','heating':'取暖费','network':'网费'}[category],h=>h.expenses.filter(e=>e.category===category).map(e=>`${escape(expenseText(e))}<span class="cell-date">${escape(LABEL.payer[e.payer]||'承担方未确认')} · ${escape(sourceLabel(e.source))}${e.unit==='sqm'?' · 计费面积 '+(e.billingArea===null?'未确认':money(e.billingArea)+'㎡'):''}</span>`).join('<br>')||'未确认']),['水电燃气',h=>h.utilities.map(u=>`${LABEL.utility[u.type]}：${LABEL.pricing[u.pricing]||'未确认'}${u.rate!==null?' · ¥'+money(u.rate)+({water:'/吨',electricity:'/度',gas:'/立方米'}[u.type]):''}`).join('<br>')||'未确认'],['家具家电',h=>`${LABEL.furnitureStatus[h.terms.furnitureStatus]||'未确认'}<br>${escape(h.terms.furniture.join('、')||'清单待补充')}${h.terms.furnitureNotes?'<br>'+escape(h.terms.furnitureNotes):''}`],['养宠物',h=>`${LABEL.pets[h.terms.pets]||'未确认'}${h.terms.petConditions?'<br>'+escape(h.terms.petConditions):''}<span class="cell-date">${escape(sourceLabel(h.terms.petsSource||h.terms.source))}</span>`]];
  if(data.settings.mode==='buy')rows.push(['单价',h=>unitPrice(h)===null?'未确认':'¥'+money(unitPrice(h))+'/㎡'],['房龄 / 产权',h=>`${h.ownership.builtYear===null?'房龄未确认':'房龄约 '+Math.max(0,new Date().getFullYear()-h.ownership.builtYear)+' 年'}<br>${LABEL.nature[h.ownership.nature]||'未确认'}<br>${h.ownership.startYear!==null&&h.ownership.years!==null?'剩余约 '+Math.max(0,h.ownership.startYear+h.ownership.years-new Date().getFullYear())+' 年（估算）':'剩余年限未确认'}`],['满五唯一',h=>h.ownership.held==='unknown'||h.ownership.sole==='unknown'?'未确认':(h.ownership.held==='yes'?'满五':'未满五')+(h.ownership.sole==='yes'?'唯一':'不唯一')],['一次性费用',h=>{const cost=onceReference(h);return `已知 ¥${money(cost.known)} + ${cost.unknown} 项未确认`;}]);
  else rows.push(['租房条款',h=>`${h.terms.deposit===null?'押金未确认':'押金 '+money(h.terms.deposit)+(h.terms.depositUnit==='months'?'个月租金':'元')}<br>${escape(h.terms.payment||'付款方式未确认')}<br>${escape(h.terms.lease||'租期未确认')}`]);
  for(const type of ['bedroom','kitchen','bathroom','living','other'])rows.push([LABEL.space[type],h=>h.spaces.filter(s=>s.type===type).map(s=>`<div><strong>${escape(s.name)}</strong><br>${observedCell(h,'space:'+s.id)}</div>`).join('<br>')||'未记录']);
  return pageHeading(`${modeLabel()} · SIDE BY SIDE`,'放在一起看','看清差异，也留意还没确认的事情。')+`<div class="compare-picker">${all.map(h=>`<label><input type="checkbox" data-compare="${h.id}" ${picked.some(p=>p.id===h.id)?'checked':''}>${escape(h.name)}</label>`).join('')}</div>${picked.length<2?`<div class="empty">${icon('compare')}<h2>选择至少两套房子</h2><p class="muted">当前已选 ${picked.length} 套，最多同时比较 4 套。</p><div class="row"><button class="btn" data-page="list">去房源列表添加</button></div></div>`:`<div class="comparison"><table aria-label="房源情况对比"><thead><tr><th scope="col">比较维度</th>${picked.map(h=>`<th scope="col"><button class="cell-open" data-open-house="${h.id}">${escape(h.name)} →</button><span class="cell-date">最近看房 ${date(latestVisit(h)?.at)}</span></th>`).join('')}</tr></thead><tbody>${rows.map(([name,content])=>`<tr><th scope="row">${name}</th>${picked.map(h=>`<td>${content(h)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted subline">← 可横向查看更多房源 · 点观察记录看原始图文。缺失项不会被当作零元或差评。</p>`}`;}
function settingsPage(){return pageHeading('LOCAL FIRST','设置与备份',isNative()?'数据保存在本机应用内，不上传云端。':'数据保存在当前浏览器，不上传云端。')+`<div class="stack"><section class="panel"><div class="panel-heading"><h2>通勤目的地</h2><button class="btn ghost small" data-action="add-target">＋ 添加</button></div><p class="muted">统一设置公司、学校等目的地，所有房源使用同一组名称。</p>${data.settings.targets.map(t=>`<div class="target-row"><div><h3>${escape(t.name)}</h3><p class="muted">${escape(t.address||'地址未填写')}</p>${hasCoordinates(t)?`<p class="muted">GPS ${t.lat.toFixed(5)}, ${t.lng.toFixed(5)}</p>`:''}</div><div class="row">${hasCoordinates(t)?`<button class="btn ghost small" data-navigate-target="${t.id}">高德导航</button>`:''}<button class="btn ghost small" data-edit-target="${t.id}">编辑</button><button class="btn ghost small danger" data-delete-target="${t.id}">删除</button></div></div>`).join('')}</section><section class="panel"><div class="panel-heading"><h2>完整备份与恢复</h2><span class="tag">包含照片与视频</span></div><div class="setting-action"><div><h3>导出 ZIP 备份 ${backupDue()?'<span class="tag">建议备份新记录</span>':''}</h3><p class="muted">上次导出：${data.settings.lastBackupAt?new Date(data.settings.lastBackupAt).toLocaleString('zh-CN'):'尚未导出'}</p></div><button class="btn" data-action="export">${icon('download')}导出</button></div><div class="setting-action"><div><h3>导入备份</h3><p class="muted">全量替换当前记录；建议先导出。</p></div><button class="btn" data-action="import">选择备份</button></div><p class="data-description" style="margin-top:17px">${isNative()?'备份包含照片、视频、地址和联系人电话，请妥善保管。卸载应用或清除应用数据会删除本机记录，请定期导出到安全位置。':'备份包含照片、视频、地址、联系人电话，请妥善保管。清除网站数据或更换浏览器可能丢失记录。导出只表示已生成下载，不保证你已将文件另存到安全位置。'}</p><input id="backup-input" type="file" accept=".zip,application/zip" hidden></section><section class="panel"><div class="panel-heading"><h2>本地数据</h2><span class="muted" id="storage-size">${data.houses.length} 套房源 · ${mediaCountLabel(data.photos)}</span></div><div class="setting-action"><div><h3>虚构示例</h3><p class="muted">仅空数据时可载入，含两套租房与两套买房。</p></div><button class="btn" data-action="demo" ${data.houses.length?'disabled':''}>载入示例</button></div><div class="setting-action"><div><h3>当前默认模式</h3><p class="muted">${modeLabel()}，顶部随时切换并记住选择。</p></div></div><p class="data-description" style="margin-top:17px">${isNative()?'安卓离线版 · 相机和相册由系统提供；定位只在点击时申请权限。没有网络也能记录、查看照片和播放视频，定位精度取决于设备与环境。':'这是手机网页原型。相机由手机系统提供；当前位置需浏览器授权。localhost / HTTPS 支持离线页面缓存，普通内网 HTTP 不支持离线重开页面和自动定位，仍可本地保存、手填地址。'}</p>${isNative()?'<button class="btn wide" style="margin-top:16px" data-action="app-settings">打开系统应用设置 / 定位权限</button>':''}</section></div>`;}
async function hydratePhotos(){for(const el of app.querySelectorAll('[data-photo]')){const id=el.dataset.photo;if(!photoURLs.has(id)){const blob=await getThumbnail(id);if(blob)photoURLs.set(id,URL.createObjectURL(blob));}if(el.isConnected&&photoURLs.has(id))el.src=photoURLs.get(id);}if(view.page==='settings'){const estimate=await estimateStorage();const el=app.querySelector('#storage-size');if(el&&estimate.usage)el.textContent=`${data.houses.length} 套 · ${mediaCountLabel(data.photos)} · 约 ${money(estimate.usage/1024/1024)} MB`;}}
function showModal(content){modalBody.innerHTML=`<div class="modal-content">${content}</div>`;if(!modal.open)modal.showModal();modalBody.querySelector('input,select,textarea,button')?.focus();}
function actions(label='保存'){return `<div class="modal-actions"><button class="btn" type="button" data-action="close-modal">取消</button><button class="btn primary">${label}</button></div>`;}
function contactDialog(id=null){const c=house().contacts.find(c=>c.id===id)||{name:'',phone:'',role:'other',company:'',remark:''};showModal(`<h2>${id?'编辑':'添加'}联系人</h2><form data-form="contact" data-id="${id||''}"><div class="fields"><label>称呼 *<input name="name" value="${escape(c.name)}" required></label><label>角色<select name="role">${Object.entries({agent:'中介',owner:house().mode==='buy'?'业主':'房东',other:'其他'}).map(([key,text])=>`<option value="${key}" ${c.role===key?'selected':''}>${text}</option>`).join('')}</select></label><label class="full">电话<input name="phone" type="tel" value="${escape(c.phone)}"></label><label class="full">公司 / 门店<input name="company" value="${escape(c.company)}"></label><label class="full">备注<input name="remark" value="${escape(c.remark)}"></label></div>${actions()}${id?`<button type="button" class="btn ghost danger" data-delete-contact="${id}">删除联系人</button>`:''}</form>`);}
function targetDialog(id=null){const t=data.settings.targets.find(t=>t.id===id)||{name:'',address:''};showModal(`<h2>${id?'编辑':'添加'}通勤目的地</h2><form data-form="target" data-id="${id||''}"><div class="stack"><label>名称 *<input name="name" value="${escape(t.name)}" required placeholder="例如：公司"></label><label>地址<input name="address" value="${escape(t.address)}"></label><div class="fields"><label>纬度（GPS/WGS84，选填）<input name="lat" type="number" min="-90" max="90" step="any" value="${escape(t.lat??'')}"></label><label>经度（GPS/WGS84，选填）<input name="lng" type="number" min="-180" max="180" step="any" value="${escape(t.lng??'')}"></label></div><button class="btn" type="button" data-action="target-location">${icon('pin')}使用当前位置</button><p class="field-hint">坐标为 GPS/WGS84；手填时请勿使用高德地图坐标。定位后仍需点击保存。</p></div>${actions()}</form>`);}
function spaceDialog(id=null){const s=house().spaces.find(s=>s.id===id)||{name:'',type:'bedroom'};showModal(`<h2>${id?'重命名':'添加'}空间</h2><form data-form="space" data-id="${id||''}"><div class="stack">${!id?`<label>空间类型<select name="type">${Object.entries(LABEL.space).map(([key,text])=>`<option value="${key}">${text}</option>`).join('')}</select></label>`:''}<label>空间名称 *<input name="name" value="${escape(s.name)}" placeholder="例如：次卧、主卫、阳台" required></label></div><p class="field-hint">名称改变后仍保留同一空间的全部看房记录。</p>${actions()}</form>`);}
function resolveField(scope,id){const h=house();if(scope==='house')return h;if(scope==='terms')return h.terms;if(scope==='ownership')return h.ownership;if(scope==='visit')return h.visits.find(v=>v.id===id);if(scope==='expense')return h.expenses.find(e=>e.id===id);if(scope==='agency'){const period=id==='once'?'once':'month';let expense=h.expenses.find(e=>e.category==='agency'&&e.period===period);if(!expense){expense=createExpense('agency',period==='once'?'一次性中介费':'每月服务费',period);expense.status='known';expense.payer='self';h.expenses.push(expense);}return expense;}if(scope==='utility')return h.utilities.find(u=>u.type===id);if(scope==='commute')return visit().commutes[Number(id)];if(scope==='note'){const v=visit();v.notes[id] ||= {text:'',updatedAt:now()};return v.notes[id];}if(scope==='photo')return data.photos.find(p=>p.id===id);}
async function updateField(el){if(!el.dataset.field||(!el.validity.valid&&!(el.type==='number'&&el.value===''&&['expense','agency'].includes(el.dataset.scope)&&el.dataset.field==='amount')))return;const {scope,id,field}=el.dataset;const obj=resolveField(scope,id);if(!obj)return;if(scope==='commute'&&field==='method'&&visit().commutes.some((c,i)=>i!==Number(id)&&c.targetId===obj.targetId&&c.method===el.value)){el.value=obj.method;toast('这个目的地已有该交通方式的记录。',true);return;}let value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(field==='at'){if(!value)return;value=new Date(value).toISOString();}if(scope==='expense'&&field==='status'&&obj.category!=='agency'&&obj.period!=='once'){obj.status=value;if(value==='free'){obj.payer='other';obj.amount=null;}else if(value==='known')obj.payer='self';}else if(scope==='agency'&&field==='amount'){obj.status='known';obj.payer='self';obj[field]=value;}else obj[field]=value;obj.updatedAt=now();if(house())house().updatedAt=now();if(scope==='note')visit().updatedAt=now();await persist();if(scope==='expense'&&['status','period','unit'].includes(field)){render();return;}if(scope==='expense'){const fee=app.querySelector(`[data-expense="${id}"] .fee-value`);if(fee)fee.textContent=expenseText(obj);}const onceEl=app.querySelector('#once-reference');if(onceEl){const once=onceReference(house());onceEl.textContent=`所有一次性费用：已知自己承担 ¥${money(once.known)} · ${once.unknown} 项未确认`;}const costEl=app.querySelector('#monthly-reference');if(costEl)costEl.textContent=summary(house());const parts=app.querySelector('#monthly-parts');if(parts){const current=monthlyReference(house());parts.innerHTML=current.items.map(x=>`${escape(x.name)}：${x.monthly===null?escape(x.reason):'¥'+money(x.monthly)+'/月'}`).join(' · ')+(current.hasAmortized?'<br>年费 / 采暖季为全年摊销参考，非实际月账单。':'');}}async function addPhotos(files){await flush();const h=house(),v=visit(),sectionKey=view.section;for(const file of files){if(!['image/jpeg','image/png','image/webp','image/gif','image/avif','video/mp4','video/webm','video/3gpp'].includes(file.type)){toast('请选择支持的图片或 MP4、WebM、3GP 视频',true);continue;}const p={id:uid(),houseId:h.id,visitId:v.id,sectionKey,filename:file.name,type:file.type,size:file.size,caption:'',createdAt:now()};data.photos.push(p);const previous=h.coverId;if(!h.coverId&&!isVideo(p))h.coverId=p.id;const snapshot=structuredClone(data);try{await commit(()=>putPhoto(snapshot,p,file));if(!isNative())photoURLs.set(p.id,URL.createObjectURL(file));}catch(error){data.photos=data.photos.filter(item=>item.id!==p.id);h.coverId=previous;throw error;}}render();toast('照片／视频已保存到本机');}
async function addPickedMedia(entries){await flush();const tokens=entries.map(e=>e.token).filter(Boolean);try{for(const entry of entries){if(!entry.token){await addPhotos([nativeFile(entry)]);continue;}const h=house(),v=visit();const p={id:uid(),houseId:h.id,visitId:v.id,sectionKey:view.section,filename:entry.name,type:entry.type,size:entry.size,caption:'',createdAt:now()};const candidate=structuredClone(data);candidate.photos.push(p);const target=candidate.houses.find(x=>x.id===h.id);if(!target.coverId&&!isVideo(p))target.coverId=p.id;await commit(()=>putPickedMedia(candidate,p,entry.token));data=candidate;}}finally{await discardPickedMedia(tokens);render();}toast('照片／视频已保存到本机');}
async function openVideo(id){await flush();const p=data.photos.find(p=>p.id===id);if(!p)return;disposePhotoViewer?.();disposePhotoViewer=null;if(fullPhotoURL)URL.revokeObjectURL(fullPhotoURL);fullPhotoURL=null;let src;if(isNative())src=`https://app.kfnote.local/media/${encodeURIComponent(id)}`;else{const blob=await getPhoto(id);if(!blob)throw new Error('视频文件缺失，请检查备份。');fullPhotoURL=URL.createObjectURL(blob);src=fullPhotoURL;}showModal(`<h2>视频记录</h2><video class="modal-video" src="${escape(src)}" controls playsinline preload="metadata"></video>${input('视频说明','photo',id,'caption',p.caption)}<p class="field-hint">${money(p.size/1024/1024)} MB · ${date(p.createdAt)}</p><div class="modal-actions"><button class="btn danger" data-delete-photo="${id}">删除视频</button><button class="btn primary" data-action="close-modal">完成</button></div>`);modalBody.querySelector('video').addEventListener('error',()=>toast('当前设备无法播放此视频，请使用设备支持的视频格式。',true),{once:true});}
async function openPhoto(id){await flush();const p=data.photos.find(p=>p.id===id);if(!p)return;const blob=await getPhoto(id);if(!blob)throw new Error('照片文件缺失，请检查备份。');disposePhotoViewer?.();if(fullPhotoURL)URL.revokeObjectURL(fullPhotoURL);fullPhotoURL=URL.createObjectURL(blob);showModal(`<h2>照片记录</h2><div data-photo-viewer><div class="photo-viewport" data-photo-viewport><img class="modal-photo" src="${fullPhotoURL}" alt="${escape(p.caption||p.filename)}" draggable="false"></div><div class="photo-zoom-controls"><button class="btn small" data-photo-zoom="out" aria-label="缩小图片">－</button><span data-photo-scale aria-label="缩放比例">100%</span><button class="btn small" data-photo-zoom="in" aria-label="放大图片">＋</button><button class="btn small" data-photo-zoom="reset">复位</button></div><p class="field-hint">双指缩放或双击放大，放大后可拖动查看。</p></div>${input('照片说明','photo',id,'caption',p.caption)}<p class="field-hint">原图 ${money(p.size/1024)} KB · ${date(p.createdAt)}</p><div class="row" style="margin-top:15px"><button class="btn" data-set-cover="${id}">设为封面</button><button class="btn" data-set-plan="${id}">设为户型图</button><button class="btn danger" data-delete-photo="${id}">删除照片</button></div><div class="modal-actions"><button class="btn primary" data-action="close-modal">完成</button></div>`);disposePhotoViewer=installPhotoViewer(modalBody.querySelector('[data-photo-viewer]'));}
function unlinkPhotos(ids){const removed=new Set(ids);data.photos=data.photos.filter(p=>!removed.has(p.id));for(const h of data.houses){if(removed.has(h.coverId))h.coverId=null;if(removed.has(h.planId))h.planId=null;}for(const id of ids){URL.revokeObjectURL(photoURLs.get(id));photoURLs.delete(id);}}
async function deletePhotoRecords(ids,change){await flush();const before=structuredClone(data);change?.();unlinkPhotos(ids);const snapshot=structuredClone(data);try{await commit(()=>deletePhotos(snapshot,ids));}catch(error){data=before;throw error;}}
async function toggleCompare(id,checked){await flush();const h=data.houses.find(h=>h.id===id),ids=data.compare[h.mode];if(checked&&!ids.includes(id)){if(ids.length>=4){render();toast('最多同时比较 4 套房源',true);return;}ids.push(id);}if(!checked)data.compare[h.mode]=ids.filter(x=>x!==id);await persist();if(view.page==='compare')render();}
function houseStatusDialog(id){const h=data.houses.find(h=>h.id===id);if(!h)return;showModal(`<h2>修改状态</h2><p class="muted">${escape(h.name)}</p><div class="stack" style="margin-top:16px">${Object.entries(LABEL.conclusion).map(([key,label])=>`<button class="btn ${h.conclusion===key?'primary':''}" data-set-conclusion="${key}" data-id="${id}">${label}${h.conclusion===key?' · 当前':''}</button>`).join('')}</div><div class="modal-actions"><button class="btn" data-action="close-modal">取消</button></div>`);}
function houseActionsDialog(id){const h=data.houses.find(h=>h.id===id);if(!h)return;showModal(`<h2>${escape(h.name)}</h2><div class="stack" style="margin-top:16px"><button class="btn" data-house-status="${id}">修改状态</button><button class="btn" data-copy-house="${id}">复制房源</button><button class="btn danger" data-request-delete-house="${id}">删除房源</button></div><div class="modal-actions"><button class="btn" data-action="close-modal">取消</button></div>`);}
function houseDeleteDialog(id){const h=data.houses.find(h=>h.id===id);if(!h)return;const count=mediaCountLabel(data.photos.filter(p=>p.houseId===id));showModal(`<h2>删除房源？</h2><p class="muted">将删除“${escape(h.name)}”、${h.visits.length} 篇日记及 ${count}，并从对比中移除。</p><div class="modal-actions"><button class="btn" data-action="close-modal">取消</button><button class="btn danger" data-confirm-delete-house="${id}">确认删除</button></div>`);}
async function copyHouse(id){await flush();const copy=duplicateHouse(data,id);const candidate=structuredClone(data);candidate.houses.push(copy.house);candidate.photos.push(...copy.photos);await commit(()=>copyPhotos(candidate,copy.pairs));data=candidate;view.filter='all';if(modal.open)modal.close();await openHouse(copy.house.id);toast('已复制房源，可独立修改');}
async function deleteHouse(id){const h=data.houses.find(h=>h.id===id);if(!h)return;const ids=data.photos.filter(p=>p.houseId===id).map(p=>p.id);await deletePhotoRecords(ids,()=>{data.houses=data.houses.filter(x=>x.id!==id);data.compare[h.mode]=data.compare[h.mode].filter(x=>x!==id);});if(modal.open)modal.close();await go('list');}
let cardPress=null,suppressedCard=null;
function cancelCardPress(){if(cardPress)clearTimeout(cardPress.timer);cardPress=null;}
document.addEventListener('pointerdown',()=>{suppressedCard=null;},true);
app.addEventListener('pointerdown',event=>{cancelCardPress();if(event.button!==0||!event.isPrimary||systemBusy)return;const card=event.target.closest('.house-card');if(!card||event.target.closest('.check-label,[data-house-status],a'))return;const press={id:card.dataset.openHouse,pointerId:event.pointerId,x:event.clientX,y:event.clientY,timer:null};cardPress=press;press.timer=setTimeout(()=>{cardPress=null;suppressedCard={id:press.id,until:Date.now()+1500};houseActionsDialog(press.id);},550);});
document.addEventListener('pointermove',event=>{if(cardPress&&event.pointerId===cardPress.pointerId&&Math.hypot(event.clientX-cardPress.x,event.clientY-cardPress.y)>10)cancelCardPress();});
document.addEventListener('pointerup',()=>{cancelCardPress();if(suppressedCard)suppressedCard.until=Date.now()+700;});
document.addEventListener('pointercancel',cancelCardPress);
window.addEventListener('blur',cancelCardPress);
app.addEventListener('contextmenu',event=>{const card=event.target.closest('.house-card');if(!card||event.target.closest('.check-label,[data-house-status]')||systemBusy)return;event.preventDefault();cancelCardPress();suppressedCard={id:card.dataset.openHouse,until:Date.now()+1500};houseActionsDialog(card.dataset.openHouse);});
async function click(event){if(suppressedCard&&event.detail>0&&Date.now()<suppressedCard.until){suppressedCard=null;event.preventDefault();return;}if(event.target.closest('.house-card .check-label'))return;const b=event.target.closest('button,[data-open-house]');if(!b||b.disabled||systemBusy)return;
  if(b.dataset.mode){await chooseMode(b.dataset.mode);return;}
  if(b.dataset.page){if(!data.settings.mode&&b.dataset.page!=='settings'){await go('entry');return;}await go(b.dataset.page);return;}
  if(b.dataset.houseStatus){await flush();houseStatusDialog(b.dataset.houseStatus);return;}
  if(b.dataset.setConclusion){const h=data.houses.find(h=>h.id===b.dataset.id);if(!h||!Object.hasOwn(LABEL.conclusion,b.dataset.setConclusion))return;h.conclusion=b.dataset.setConclusion;h.updatedAt=now();await persist();modal.close();render();return;}
  if(b.dataset.requestDeleteHouse){await flush();houseDeleteDialog(b.dataset.requestDeleteHouse);return;}
  if(b.dataset.copyHouse){b.disabled=true;try{await systemOperation(()=>copyHouse(b.dataset.copyHouse));}finally{b.disabled=false;}return;}
  if(b.dataset.confirmDeleteHouse){b.disabled=true;try{await deleteHouse(b.dataset.confirmDeleteHouse);}finally{b.disabled=false;}return;}
  if(b.dataset.openHouse){await openHouse(b.dataset.openHouse);return;}
  if(b.dataset.filter){view.filter=b.dataset.filter;render();return;}
  if(b.dataset.tab){await flush();view.tab=b.dataset.tab;render();return;}
  if(b.dataset.section){await flush();view.section=b.dataset.section;render();return;}
  if(b.dataset.editContact){contactDialog(b.dataset.editContact);return;}
  if(b.dataset.renameSpace){spaceDialog(b.dataset.renameSpace);return;}
  if(b.dataset.editTarget){targetDialog(b.dataset.editTarget);return;}
  if(b.dataset.navigateTarget){const target=data.settings.targets.find(t=>t.id===b.dataset.navigateTarget);if(target)await navigateTo({...target,name:target.name});return;}
  if(b.dataset.navigateHouse){const h=data.houses.find(item=>item.id===b.dataset.navigateHouse);if(h)await navigateTo({lat:h.lat,lng:h.lng,name:h.name});return;}
  if(b.dataset.openPhoto){const p=data.photos.find(p=>p.id===b.dataset.openPhoto);if(isVideo(p))await openVideo(p.id);else await openPhoto(b.dataset.openPhoto);return;}
  if(b.dataset.observationHouse){await openHouse(b.dataset.observationHouse,['environment','traffic','amenities'].includes(b.dataset.observationKey)?'basic':'diary');view.visitId=b.dataset.observationVisit;view.section=b.dataset.observationKey;render();return;}
  if(b.dataset.setCover||b.dataset.setPlan){const id=b.dataset.setCover||b.dataset.setPlan;if(isVideo(data.photos.find(p=>p.id===id))){toast('封面和户型图请选择图片。',true);return;}house()[b.dataset.setCover?'coverId':'planId']=id;await persist();toast(b.dataset.setCover?'已设为封面':'已设为户型图');return;}
  if(b.dataset.deletePhoto){const p=data.photos.find(p=>p.id===b.dataset.deletePhoto);if(!confirm(isVideo(p)?'删除这个视频？':'删除这张照片？若被封面或户型图引用，会一并解除引用。'))return;await deletePhotoRecords([b.dataset.deletePhoto]);modal.close();render();return;}
  if(b.dataset.deleteContact){if(!confirm('删除这个联系人？'))return;house().contacts=house().contacts.filter(c=>c.id!==b.dataset.deleteContact);await persist();modal.close();render();return;}
  if(b.dataset.deleteTarget){const id=b.dataset.deleteTarget;if(!confirm('删除目的地及所有日记中关联的通勤记录？'))return;data.settings.targets=data.settings.targets.filter(t=>t.id!==id);for(const h of data.houses)for(const v of h.visits)v.commutes=v.commutes.filter(c=>c.targetId!==id);await persist();render();return;}
  if(b.dataset.deleteCommute){visit().commutes.splice(Number(b.dataset.deleteCommute),1);await persist();render();return;}
  const action=b.dataset.action;if(!action)return;
  if(action==='close-modal'){await flush();modal.close();render();return;}
  if(action==='retry-save'){await persist();toast('已重新保存');return;}
  if(action==='generate-introduction'){await flush();showModal(`<h2>房源介绍</h2><p class="muted">根据已记录的信息汇总，可修改后复制。</p><label class="subline">介绍文字<textarea id="house-introduction" rows="9">${escape(houseIntroduction(house(),data))}</textarea></label><div class="modal-actions"><button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-action="copy-introduction">复制介绍</button></div>`);return;}
  if(action==='copy-introduction'){const field=modalBody.querySelector('#house-introduction'),text=field?.value.trim();if(!text){toast('介绍内容为空，请先填写。',true);return;}if(isNative())await nativePlatform('copyText',{text});else{try{await navigator.clipboard.writeText(text);}catch{field.focus();field.select();if(!document.execCommand('copy'))throw new Error('复制失败，请长按文字手动复制。');}}toast('房源介绍已复制');return;}
  if(action==='app-settings'){await nativePlatform('appSettings');return;}
  if(action==='reload'){location.reload();return;}
  if(action==='demo'){if(data.houses.length){toast('已有记录，示例只能在空数据时载入。',true);return;}if(!confirm('载入四套虚构示例？这些是演示数据。'))return;data=createDemoState();await persist();await go('list');return;}
  if(action==='add-contact'){contactDialog();return;}
  if(action==='add-target'){targetDialog();return;}
  if(action==='add-space'){spaceDialog();return;}
  if(action==='new-visit'){await flush();const v=createVisit();house().visits.push(v);view.visitId=v.id;await persist();render();toast('已新建复看日记，旧记录保留');return;}
  if(action==='delete-visit'){const v=visit();const ids=data.photos.filter(p=>p.visitId===v.id).map(p=>p.id);if(!confirm(`删除本次日记及 ${mediaCountLabel(data.photos.filter(p=>ids.includes(p.id)))}？历史记录不会自动合并。`))return;await deletePhotoRecords(ids,()=>{house().visits=house().visits.filter(x=>x.id!==v.id);view.visitId=latestVisit(house())?.id||null;});render();return;}
  if(action==='delete-house'){const h=house(),ids=data.photos.filter(p=>p.houseId===h.id).map(p=>p.id);if(!confirm(`删除“${h.name}”、${h.visits.length} 篇日记及 ${mediaCountLabel(data.photos.filter(p=>ids.includes(p.id)))}？`))return;await deleteHouse(h.id);return;}
  if(action==='choose-photo'||action==='take-photo'||action==='take-video'){if(isNative()){await systemOperation(async()=>{await flush();const result=await nativePlatform(action==='take-photo'?'takePhoto':action==='take-video'?'takeVideo':'pickMedia');if(result)await addPickedMedia(Array.isArray(result)?result:[result]);});}else app.querySelector(action==='take-photo'?'#camera-input':action==='take-video'?'#video-camera-input':'#photo-input').click();return;}
  if(action==='location'||action==='target-location'){const form=b.closest('form');const targetForm=form?.dataset.form==='target';const newHouseForm=form?.id==='new-house';const existingHouse=!targetForm&&!newHouseForm;await systemOperation(async()=>{if(existingHouse)await flush();toast('正在获取当前位置…');const coords=await currentCoordinates();if(!coords)return;if(targetForm||newHouseForm){form.elements.lat.value=String(coords.lat);form.elements.lng.value=String(coords.lng);if(newHouseForm)form.elements.locationConfirmed.value='true';toast('位置已填入表单，请检查后保存。');return;}house().lat=coords.lat;house().lng=coords.lng;house().locationConfirmed=true;await persist();render();toast('房源位置已保存');});return;}
  if(action==='sync-facts'){showModal(`<h2>更新已核实的房源事实</h2><p class="muted">仅点击确认后更新；原日记内容保持独立。</p><form data-form="facts"><div class="fields" style="margin-top:17px"><label>朝向<select name="direction">${Object.entries(LABEL.direction).map(([key,label])=>`<option value="${key}" ${house().direction===key?'selected':''}>${label}</option>`).join('')}</select></label><label>面积（㎡）<input name="area" type="number" min="0.01" step="any" value="${escape(house().area)}"></label></div>${actions('确认更新房源')}</form>`);return;}
  if(action==='custom-furniture'){showModal(`<h2>其他家具 / 家电</h2><form data-form="furniture"><label>名称 *<input name="name" required placeholder="例如：烘干机"></label>${actions('添加')}</form>`);return;}
  if(action==='add-expense'){showModal(`<h2>添加费用</h2><form data-form="expense"><label>费用名称 *<input name="name" required placeholder="例如：停车费"></label><label>类型<select name="period"><option value="month">固定月费</option><option value="quarter">季度费用</option><option value="year">年费</option><option value="once">一次性费用</option></select></label>${actions('添加')}</form>`);return;}
  if(action==='add-commute'){if(!data.settings.targets.length){toast('请先到设置添加通勤目的地。');return;}showModal(`<h2>记录通勤</h2><form data-form="commute"><div class="fields"><label>目的地<select name="targetId">${data.settings.targets.map(t=>`<option value="${t.id}">${escape(t.name)}</option>`).join('')}</select></label><label>交通方式<select name="method">${Object.entries(LABEL.method).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label>耗时（分钟）<input name="minutes" type="number" min="0" step="any" placeholder="未知留空"></label><label>记录来源<input name="source" placeholder="例如：现场计时 / 地图估算"></label></div>${actions('添加')}</form>`);return;}
  if(action==='export'){await systemOperation(async()=>{await flush();toast('正在打包文字、照片与视频…');const blob=await exportBackup();const name=`看房日记备份-${localDateTime(now()).replace(/[:T]/g,'-')}.zip`;if(isNative()){const result=await nativePlatform('exportBackup',{base64:await blobBase64(blob),name});if(result===null)return;}else{const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}data.settings.lastBackupAt=now();await persist();render();toast(isNative()?'备份文件已保存':'已生成备份下载，请确认文件已保存。');});return;}
  if(action==='import'){await flush();if(isNative()){await systemOperation(async()=>{const result=await nativePlatform('importBackup');if(result)await restoreBackup(nativeFile(result));});}else app.querySelector('#backup-input').click();return;}
}
async function systemOperation(operation){systemBusy=true;app.inert=true;try{return await operation();}finally{systemBusy=false;app.inert=false;}}
async function restoreBackup(file){await flush();if(!confirm(`导入“${file.name}”将全量替换当前房源、照片、视频和联系人。\n建议先导出当前备份。是否继续？`))return;toast('正在校验并恢复备份…');data=await importBackup(file);for(const url of photoURLs.values())URL.revokeObjectURL(url);photoURLs.clear();view={...view,page:data.settings.mode?'list':'entry',houseId:null,visitId:null};render();toast('备份已完整恢复');}
async function submit(event){event.preventDefault();const form=event.target;if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));await flush();if(form.id==='new-house'){const name=values.name.trim();if(!name)return;const coordinates=coordinatesFromForm(values);if(!coordinates){toast('纬度和经度需要成对填写，并处于有效范围内。',true);return;}const h=createHouse(data.settings.mode,{name,price:values.price===''?null:Number(values.price),area:values.area===''?null:Number(values.area),areaBasis:values.areaBasis,layout:values.layout,address:values.address,channel:values.channel,...coordinates,locationConfirmed:values.locationConfirmed==='true'});if(values.contactName||values.phone)h.contacts.push({id:uid(),name:values.contactName||'联系人',phone:values.phone,role:values.channel==='owner'?'owner':values.channel==='agent'?'agent':'other',company:'',remark:''});data.houses.push(h);await persist();await openHouse(h.id);return;}
  const kind=form.dataset.form,id=form.dataset.id;
  if(kind==='contact'){if(!values.name.trim())return;const c={...values,id:id||uid()};if(id)Object.assign(house().contacts.find(c=>c.id===id),c);else house().contacts.push(c);}
  if(kind==='space'){if(!values.name.trim())return;if(id)house().spaces.find(s=>s.id===id).name=values.name.trim();else{const s=createSpace(values.type,values.name.trim());house().spaces.push(s);if(view.tab==='diary')view.section='space:'+s.id;}}
  if(kind==='target'){if(!values.name.trim())return;const coordinates=coordinatesFromForm(values);if(!coordinates){toast('纬度和经度需要成对填写，并处于有效范围内。',true);return;}const t={name:values.name,address:values.address||'',id:id||uid(),...coordinates};if(id)Object.assign(data.settings.targets.find(t=>t.id===id),t);else data.settings.targets.push(t);}
  if(kind==='expense'){if(!values.name.trim())return;house().expenses.push(createExpense('other',values.name.trim(),values.period));}
  if(kind==='furniture'){if(!values.name.trim())return;if(!house().terms.furniture.includes(values.name.trim()))house().terms.furniture.push(values.name.trim());}
  if(kind==='commute'){if(visit().commutes.some(c=>c.targetId===values.targetId&&c.method===values.method)){toast('这个目的地和交通方式已有记录，请直接编辑。',true);return;}visit().commutes.push({...values,minutes:values.minutes===''?null:Number(values.minutes)});}
  if(kind==='facts'){house().direction=values.direction;house().area=values.area===''?null:Number(values.area);house().updatedAt=now();}
  await persist();modal.close();render();
}
function report(error){console.error(error);toast(error.message||'操作失败，请重试。',true);}
document.addEventListener('toggle',event=>{const el=event.target;if(el.dataset.expense){if(el.open)view.openExpenses.add(el.dataset.expense);else view.openExpenses.delete(el.dataset.expense);}},true);
document.addEventListener('click',event=>{click(event).catch(report);});
document.addEventListener('submit',event=>{submit(event).catch(report);});
document.addEventListener('input',event=>{const el=event.target;if(el.matches('input:not([type=checkbox]):not([type=file]),textarea')&&el.dataset.field)updateField(el).catch(report);});
document.addEventListener('change',event=>{(async()=>{const el=event.target;if(el.matches('select,input[type=checkbox]')&&el.dataset.field){await updateField(el);return;}if(el.id==='visit-picker'||el.id==='basic-visit-picker'){await flush();view.visitId=el.value;render();return;}if(el.dataset.compare){await toggleCompare(el.dataset.compare,el.checked);return;}if(el.dataset.furniture){const t=house().terms;t.furniture=el.checked?[...new Set([...t.furniture,el.dataset.furniture])]:t.furniture.filter(x=>x!==el.dataset.furniture);await persist();return;}if(el.id==='photo-input'||el.id==='camera-input'||el.id==='video-camera-input'){await addPhotos([...el.files]);return;}if(el.id==='backup-input'&&el.files.length){try{await systemOperation(()=>restoreBackup(el.files[0]));}finally{el.value='';}}})().catch(report);});
modal.addEventListener('cancel',event=>{if(pending||saveError){event.preventDefault();toast('请先等当前内容保存完成。');}});
window.addEventListener('beforeunload',event=>{if(pending||saveError){event.preventDefault();event.returnValue='';}});
modal.addEventListener('close',()=>{const video=modalBody.querySelector('video');if(video){video.pause();video.removeAttribute('src');video.load();}suppressedCard=null;disposePhotoViewer?.();disposePhotoViewer=null;if(fullPhotoURL){URL.revokeObjectURL(fullPhotoURL);fullPhotoURL=null;}});
window.KFAndroidBack=()=>{if(systemBusy||pending||saveError){toast('请先等当前操作完成或重试保存。');return true;}if(modal.open){modal.close();render();return true;}if(!data)return false;if(view.page==='detail'||view.page==='new'||view.page==='compare'||view.page==='settings'){go(data.settings.mode?'list':'entry').catch(report);return true;}return false;};

async function start(){try{data=await loadState();if(data)validateState(data);else{data=createState();await saveState(data);}view.page=data.settings.mode?'list':'entry';render();if(!isNative()&&'serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}catch(error){app.innerHTML=`<div class="empty" style="margin:30px"><h2>暂时无法打开本地记录</h2><p class="muted subline">${escape(error.message)}</p><button class="btn" style="margin-top:20px" data-action="reload">重新打开</button></div>`;}}
start();
